CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY, balance BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS submissions (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, proof TEXT NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'pending', amount BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS withdrawals (id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,amount BIGINT NOT NULL,destination TEXT NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'pending',request_id VARCHAR(100) NOT NULL,UNIQUE(user_id,request_id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS credits (request_id VARCHAR(100) PRIMARY KEY,admin_id BIGINT NOT NULL,user_id BIGINT NOT NULL,amount BIGINT NOT NULL,created_at BIGINT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS web_submissions (user_id BIGINT NOT NULL,request_id VARCHAR(100) NOT NULL,submission_id BIGINT NOT NULL,PRIMARY KEY(user_id,request_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS telegram_updates (id BIGINT PRIMARY KEY,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
